INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (81, 'gateway-route.json', 'GATEWAY_GROUP', '[ {\n  \"id\" : \"iwindplus-mgt\",\n  \"uri\" : \"lb://iwindplus-mgt\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/mgt/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"管理服务\"\n  },\n  \"order\" : \"1\"\n}, {\n  \"id\" : \"iwindplus-log\",\n  \"uri\" : \"lb://iwindplus-log\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/log/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"日志服务\"\n  },\n  \"order\" : \"2\"\n}, {\n  \"id\" : \"iwindplus-auth\",\n  \"uri\" : \"lb://iwindplus-auth\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/api/auth/**\"\n    }\n  } ],\n  \"filters\" : [ {\n    \"name\" : \"StripPrefix\",\n    \"args\" : {\n      \"parts\" : \"2\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"认证服务\"\n  },\n  \"order\" : \"3\"\n}, {\n  \"id\" : \"iwindplus-im\",\n  \"uri\" : \"lb://iwindplus-im\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/im/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"即时通讯服务\"\n  },\n  \"order\" : \"4\"\n}, {\n  \"id\" : \"iwindplus-im-ws\",\n  \"uri\" : \"lb:ws://iwindplus-im-ws\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/imWs/**\"\n    }\n  } ],\n  \"filters\" : [ {\n    \"name\" : \"StripPrefix\",\n    \"args\" : {\n      \"parts\" : \"2\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"即时通讯websocket服务\"\n  },\n  \"order\" : \"5\"\n}, {\n  \"id\" : \"iwindplus-setup\",\n  \"uri\" : \"lb://iwindplus-setup\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/setup/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"配置服务\"\n  },\n  \"order\" : \"6\"\n}, {\n  \"id\" : \"iwindplus-flow\",\n  \"uri\" : \"lb://iwindplus-flow\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/flow/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"流程服务\"\n  },\n  \"order\" : \"7\"\n}, {\n  \"id\" : \"iwindplus-dtx\",\n  \"uri\" : \"lb://iwindplus-dtx\",\n  \"predicates\" : [ {\n    \"name\" : \"Path\",\n    \"args\" : {\n      \"_genkey_0\" : \"/admin/dtx/**\"\n    }\n  } ],\n  \"metadata\" : {\n    \"name\" : \"全局事务服务\"\n  },\n  \"order\" : \"8\"\n} ]', 'e890224e0ff6dd0fe5a27efcc6c77604', '2026-01-10 22:28:50', '2026-08-30 21:21:56', NULL, '192.168.1.102', '', 'iwindplus-local', NULL, NULL, NULL, 'json', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (83, 'iwindplus-dtx-local.yml', 'IWINDPLUS_GROUP', 'server:\n  # 配置启动的接口\n  port: 9012\n  servlet:\n    application-display-name: 分布式事务服务\ncross:\n  # 是否开启跨域\n  enabled: false\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: tccThreadPool\n      threadPoolAliasName: tcc分布式事务线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-dtx?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: ${mysql-password}\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: ${xxl-job-access-token}\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 是否启用签名（数据防篡改用）\n      enabled-sign: true\n      # 密钥（数据防篡改用）\n      secret-key: ${mybatis-field-crypto-secret-key}\n      # 算法\n      algorithm: AES\n      # 公钥\n      public-key: ${mybatis-field-crypto-public-key:}\n      # 私钥\n      private-key: ${mybatis-field-crypto-private-key:}\n      # 密钥\n      key: ${mybatis-field-crypto-key:}\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.dtx.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '2e80f453af050ddad55778ec46eed2ee', '2026-02-08 13:19:12', '2026-08-30 22:35:56', 'nacos', '192.168.65.1', '', 'iwindplus-local', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (91, 'iwindplus-common.yml', 'IWINDPLUS_GROUP', 'server:\n  # 优雅停机\n  shutdown: graceful\n  servlet:\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\nspring:\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  lifecycle:\n    # 优雅停机时，每个生命周期阶段允许等待的最大时间\n    # 超过该时间后，Spring 将继续执行后续关闭流程\n    timeout-per-shutdown-phase: 60s\n  servlet:\n    multipart:\n      enabled: true\n      maxFileSize: 1GB\n      maxRequestSize: 10GB\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    loadbalancer:\n      cache:\n        # 开启缓存，如果注册中心有自己的缓存，那么就可以禁用loadbalancer的缓存\n        enabled: true\n        # 过期时间10s\n        ttl: 10\n        # 容量256M\n        capacity: 256\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    public-key: ${filter-crypto-public-key:}\n    # 私钥\n    private-key: ${filter-crypto-private-key:}\n    # 密钥\n    key: ${filter-crypto-key:}\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\nloadbalancer:\n  monitor:\n    enabled: true\n  gray:\n    enabled: true\n    # 灰度策略类型（whitelist: 白名单策略，percentage: 百分比策略）\n    strategy: PERCENTAGE\n    # 灰度百分比（0-100）\n    percentage: 10\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      public-key: ${response-body-crypto-public-key:}\n      # 私钥\n      private-key: ${response-body-crypto-private-key:}\n      # 密钥\n      key: ${response-body-crypto-key:}\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: ${httpClient-apiProtection-access-key:}\n      secret-key: ${httpClient-apiProtection-secret-key:}\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  fallback:\n    # 是否启用熔断回退\n    enabled: true\n  sentinel:\n    enabled: true\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: false\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      webhook: https://open.feishu.cn/open-apis/bot/v2/hook/cbdc5945-1cf9-42e4-84d5-a46ce56c99ef\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nmanagement:\n  observations:\n    enable:\n      http: true\n  server:\n    port: ${server.port}\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile\n        exclude: env,heapdump,threaddump,mappings\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n    distribution:\n      percentiles-histogram:\n        http.server.requests: true\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\n', 'e1bc12ebffe56a6957d0183153b0aa7f', '2026-08-24 23:18:51', '2026-08-30 22:36:01', 'nacos', '192.168.65.1', '', 'iwindplus-local', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (93, 'iwindplus-circuitbreaker.yml', 'IWINDPLUS_GROUP', '# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    enabled: true\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅 Feign 技术类异常计入失败；业务、认证、限流异常不触发熔断\n        record-exceptions:\n          - com.iwindplus.base.feign.exception.FeignTechnicalException\n          - feign.RetryableException\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n        ignore-exceptions:\n          - com.iwindplus.base.feign.exception.FeignBusinessException\n          - com.iwindplus.base.feign.exception.FeignAuthenticationException\n          - com.iwindplus.base.feign.exception.FeignRateLimitException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0', '0b3d224dd2f8a7c443f1b082ec602456', '2026-08-26 10:42:12', '2026-08-30 22:36:06', 'nacos', '192.168.65.1', '', 'iwindplus-local', '', NULL, NULL, 'yaml', NULL, '');
COMMIT;

-- ----------------------------
-- Table structure for config_info_aggr
-- ----------------------------
DROP TABLE IF EXISTS `config_info_aggr`;
CREATE TABLE `config_info_aggr` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `data_id` varchar(255) COLLATE utf8mb3_bin NOT NULL COMMENT 'data_id',
  `group_id` varchar(128) COLLATE utf8mb3_bin NOT NULL COMMENT 'group_id',
  `datum_id` varchar(255) COLLATE utf8mb3_bin NOT NULL COMMENT 'datum_id',
  `content` longtext COLLATE utf8mb3_bin NOT NULL COMMENT '内容',
  `gmt_modified` datetime NOT NULL COMMENT '修改时间',
  `app_name` varchar(128) COLLATE utf8mb3_bin DEFAULT NULL,
  `tenant_id` varchar(128) COLLATE utf8mb3_bin DEFAULT '' COMMENT '租户字段',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_configinfoaggr_datagrouptenantdatum` (`data_id`,`group_id`,`tenant_id`,`datum_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin ROW_FORMAT=DYNAMIC COMMENT='增加租户字段';

-- ----------------------------
-- Records of config_info_aggr
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for config_info_beta
