-- ----------------------------
-- Table structure for group_capacity
-- ----------------------------
DROP TABLE IF EXISTS `group_capacity`;
CREATE TABLE `group_capacity` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `group_id` varchar(128) COLLATE utf8mb3_bin NOT NULL DEFAULT '' COMMENT 'Group ID，空字符表示整个集群',
  `quota` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '配额，0表示使用默认值',
  `usage` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '使用量',
  `max_size` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '单个配置大小上限，单位为字节，0表示使用默认值',
  `max_aggr_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '聚合子配置最大个数，，0表示使用默认值',
  `max_aggr_size` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '单个聚合数据的子配置大小上限，单位为字节，0表示使用默认值',
  `max_history_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '最大变更历史数量',
  `gmt_create` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT current_timestamp() COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_group_id` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin COMMENT='集群、各Group容量信息表';

-- ----------------------------
-- Records of group_capacity
-- ----------------------------
BEGIN;
INSERT INTO `group_capacity` (`id`, `group_id`, `quota`, `usage`, `max_size`, `max_aggr_count`, `max_aggr_size`, `max_history_count`, `gmt_create`, `gmt_modified`) VALUES (1, '', 0, 18, 0, 0, 0, 0, '2025-11-01 20:01:24', '2026-08-30 23:29:49');
COMMIT;

-- ----------------------------
-- Table structure for his_config_info
-- ----------------------------
DROP TABLE IF EXISTS `his_config_info`;
CREATE TABLE `his_config_info` (
  `id` bigint(20) unsigned NOT NULL COMMENT 'id',
  `nid` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'nid, 自增标识',
  `data_id` varchar(255) COLLATE utf8mb3_bin NOT NULL COMMENT 'data_id',
  `group_id` varchar(128) COLLATE utf8mb3_bin NOT NULL COMMENT 'group_id',
  `app_name` varchar(128) COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'app_name',
  `content` longtext COLLATE utf8mb3_bin NOT NULL COMMENT 'content',
  `md5` varchar(32) COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'md5',
  `gmt_create` datetime NOT NULL DEFAULT current_timestamp() COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT current_timestamp() COMMENT '修改时间',
  `src_user` text COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'source user',
  `src_ip` varchar(50) COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'source ip',
  `op_type` char(10) COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'operation type',
  `tenant_id` varchar(128) COLLATE utf8mb3_bin DEFAULT '' COMMENT '租户字段',
  `encrypted_data_key` varchar(1024) COLLATE utf8mb3_bin NOT NULL DEFAULT '' COMMENT '密钥',
  `publish_type` varchar(50) COLLATE utf8mb3_bin DEFAULT 'formal' COMMENT 'publish type gray or formal',
  `gray_name` varchar(50) COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'gray name',
  `ext_info` longtext COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'ext info',
  PRIMARY KEY (`nid`),
  KEY `idx_gmt_create` (`gmt_create`),
  KEY `idx_gmt_modified` (`gmt_modified`),
  KEY `idx_did` (`data_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17269 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin COMMENT='多租户改造';

-- ----------------------------
-- Records of his_config_info
-- ----------------------------
BEGIN;
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (3, 17243, 'iwindplus-mgt-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9001\n  servlet:\n    application-display-name: 管理服务\ncross:\n  # 是否开启跨域\n  enabled: false\nfilter:\n  xss:\n    # 是否启用跳过.\n    enabled-skip: true\n    # 忽略的API\n    ignored-api:\n      - /i18nProject/save\n      - /i18nProject/edit\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\nasync-task:\n  # 是否开启异步命令\n  enabled: true\n  # 是否开启成功后删除数据\n  enabled-success-delete: true\n  # 是否开启异常信息截取\n  enabled-exception-capture: true\n  # 异常信息截取长度\n  exception-capture-length: 4000\n  # 是否开启job\n  job:\n    enabled: true\n  web:\n    # 接口路径\n    path: admin/mgt/asyncTask\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: asyncTaskThreadPool\n      threadPoolAliasName: 异步任务线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: asyncTaskSubThreadPool\n      threadPoolAliasName: 异步任务子线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerThreadPool\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 0\n      queueTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: disruptorThreadPool\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-mgt?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: ${mysql-username}\n    # 数据库密码\n    password: ${mysql-password}\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerThreadPool\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          enable-reactive: true\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-appCert-topic\n            group: iwindplus-appCert-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-apiWhiteList-topic\n            group: iwindplus-apiWhiteList-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-ipBlackList-topic\n            group: iwindplus-ipBlackList-group\n            # 是否自动创建\n            auto-create: true\nrocket:\n  multi:\n    enabled: true\n    default-cluster: default\n    clusters:\n      default:\n        nameServer: 127.0.0.1:9876\n        # 生产者配置\n        producer:\n          send-msg-timeout: 1000\n        # 消费者配置\n        consumer:\n          consume-message-batch-max-size: 10\n          # 绑定关系配置\n          bindings:\n            - topic: iwindplus-server-topic\n              group: iwindplus-server-group\n              tag: \"*\"\n            - topic: iwindplus-server1-topic\n              group: iwindplus-server-group\n              tag: \"*\"\nrabbit:\n  multi:\n    enabled: true\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        addresses: 127.0.0.1:5672\n        username: ${rabbit-default-username}\n        password: ${rabbit-default-password}\n        virtual-host: /\n        connection-timeout: 5000\n        # 生产者配置\n        producer:\n          #这个配置是保证提供者确保消息推送到交换机中，不管成不成功，都会回调\n          publisher-confirm-type: correlated\n          #保证交换机能把消息推送到队列中\n          publisher-returns: true\n        # 消费者配置\n        consumer:\n          concurrency: 1\n          acknowledgeMode: MANUAL\n          enabledBatchListener: false\n          # 绑定关系配置\n          bindings:\n            - auto-create: true\n              routingKeys:\n                - iwindplus.server.demo\n              exchange:\n                name: iwindplus.server.demo\n                type: topic\n              queue:\n                name: iwindplus.server.demo\n                durable: true\n                arguments:\n                  x-queue-mode: lazy\n              group: iwindplus.server.demo\n            - auto-create: true\n              routingKeys:\n                - iwindplus.server.demo.batch\n              exchange:\n                name: iwindplus.server.demo.batch\n                type: topic\n              queue:\n                name: iwindplus.server.demo.batch\n                durable: true\n                arguments:\n                  x-queue-mode: lazy\n              group: iwindplus.server.demo.batch\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: ${xxl-job-access-token}\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 是否启用签名（数据防篡改用）\n      enabled-sign: true\n      # 密钥（数据防篡改用）\n      secret-key: ${mybatis-field-crypto-secret-key}\n      # 算法\n      algorithm: AES\n      # 公钥\n      public-key: ${mybatis-field-crypto-public-key:}\n      # 私钥\n      private-key: ${mybatis-field-crypto-private-key:}\n      # 密钥\n      key: ${mybatis-field-crypto-key:}\nmgt:\n  ws:\n    # 是否开启ws推送\n    enabled: true\n  mail:\n    # 邮件模板编码\n    tpl-code: c3f67fd355dd6098156053f68285ba3e\n  sms:\n    # 短信模板编码\n    tpl-code: c3f67fd354dd6098154053f68285ba35\n  oss:\n    # 对象存储模板编码\n    tpl-code: c3f67fd355dd6098156053f68385ba34\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.mgt.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '2768b9c0d74ea4af51147d123939ba09', '2026-08-30 22:34:48', '2026-08-30 22:34:48', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (15, 17245, 'iwindplus-gateway-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9000\n  servlet:\n    application-display-name: 网关服务\ncross:\n  # 是否开启跨域\n  enabled: true\ngateway:\n  rate-limiter:\n    # 是否开启限流过滤器\n    enabled: true\n    # 最大缓存数量\n    maxSize: 1000\n    # 缓存超时时间\n    cache-timeout: 10m\n    # 缓存刷新时间\n    cache-refresh: 15m\n    # 限流类型（可选，默认：OVERALL）\n    rate-type: OVERALL\n    # 限流次数，每个时间窗口允许请求数量（可选，默认：1000）\n    rate: 2000\n    # 限流速率（可选，默认：1s）\n    rate-interval: 1s\n  base:\n    # 是否开启基础过滤器\n    enabled: true\n    # 是否启用从cookie中读取token\n    enabled-auth-cookie: false\n    # 是否启用相对路径\n    enabled-relative-path: false\n  api-white-list:\n    # API白名单过滤器\n    enabled: true\n    # 最大缓存数量\n    maxSize: 1000\n    # 缓存超时时间\n    cache-timeout: 10m\n    # 缓存刷新时间\n    cache-refresh: 15m\n    # 忽略的API\n    ignored-api:\n      - /admin/imWs/ws\n      - /admin/setup/wechat/getWechatMpQrCode\n      - /admin/setup/wechat/getWechatMpQrCodeCallback\n      - /admin/setup/wechat/getWechatMaCodeByMobile\n      - /admin/setup/wechat/getWechatMaCodeByUserInfo\n      - /admin/setup/wechat/getWechatMaQrCode\n      - /admin/setup/sms/sendCaptcha\n      - /admin/setup/mailbox/sendCaptcha\n      - /admin/setup/oss/uploadFile\n      - /admin/mgt/thirdBindGrant/editUser\n  ip-black-list:\n    # 是否开启IP黑名单过滤器\n    enabled: true\n    # 最大缓存数量\n    maxSize: 1000\n    # 缓存超时时间\n    cache-timeout: 10m\n    # 缓存刷新时间\n    cache-refresh: 15m\n  api-sign:\n    # 是否开启API签名过滤器\n    enabled: false\n    # 最大缓存数量\n    maxSize: 1000\n    # 缓存超时时间\n    cache-timeout: 10m\n    # 缓存刷新时间\n    cache-refresh: 15m\n    # 忽略拦截的API\n    ignored-api:\n      - /static/**\n      - /doc.html\n      - /api-docs\n      - /inner/**\n      - /actuator/**\n      - /admin/imWs/ws\n      - /oauth2/token\n  auth:\n    # 是否开启权限过滤器\n    enabled: true\n    # 是否启用远程token校验\n    enabled-remote-token: false\n    # 是否开启API权限过滤器\n    enabled-api-permission: false\n    # token最大缓存数量\n    token-maxSize: 1000\n    # token缓存超时时间\n    token-cache-timeout: 5m\n    # token缓存刷新时间\n    token-cache-refresh: 10m\n    # 权限最大缓存数量\n    permission-maxSize: 1000\n    # 权限缓存超时时间\n    permission-cache-timeout: 10m\n    # 权限缓存刷新时间\n    permission-cache-refresh: 15m\n    # 忽略鉴权的API\n    ignored-api:\n      - /admin/auth/oauth2/logout\n      - /admin/setup/mail/config/listEnabled\n      - /admin/setup/mail/tpl/listDisabled\n      - /admin/setup/oss/listSignUrl\n      - /admin/im/direct/msg/editMsgStatus\n    # 通用都有权限的API\n    general-api:\n      - /admin/mgt/user/getUserInfo\n      - /admin/mgt/user/editChangeOrg\n      - /admin/mgt/user/getGaQrcode\n      - /admin/mgt/user/editGaBindFlag\n      - /admin/log/login/log/getLoginInfo\n  log:\n    # 是否开启日志过滤器\n    enabled: true\n    # 是否启用记录错误日志\n    enabled-error: true\n    # 采样率（10：代表10%的采样率）\n    sample-rate: 100\n    # 是否启用获取请求头\n    enabled-request-header: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 请求体限制大小，超过部分丢弃，单位：KB\n    limit-request-body: 2\n    # 是否启用获取响应头\n    enabled-response-header: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n    # 响应体限制大小，超过部分丢弃，单位：KB\n    limit-response-body: 2\n    # 忽略的API\n    ignored-api:\n      - /admin/imWs/ws\n      - /admin/setup/region/**\n      - /admin/log/gateway/log/**\n      - /admin/log/login/log/**\n      - /admin/log/operation/log/**\n\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: routeThreadPool\n      threadPoolAliasName: 路由线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      threadNamePrefix: routeTask\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerThreadPool\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 0\n      queueTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: disruptorThreadPool\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  reactor:\n    context-propagation: AUTO\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\n  cloud:\n    gateway:\n      httpclient:\n        pool:\n          type: ELASTIC\n          max-connections: 4000\n          max-connections-per-route: 500\n          acquire-timeout: 45000\n          max-idle-time: 60s\n          max-life-time: 300s\n        # 连接超时时间\n        connect-timeout: 10000\n        # 响应超时时间\n        response-timeout: 10s\n        # 请求行最大长度\n        max-initial-line-length: 8KB\n        # header 最大长度\n        max-header-size: 64KB\n        ssl:\n          handshake-timeout: 5s\n          close-notify-flush-timeout: 3s\n        compression: true\n        wiretap: false\n      discovery:\n        locator:\n          # 是否与服务发现组件进行结合，通过serviceId转发到具体服务实例\n          # 是否开启基于服务发现的路由规则\n          enabled: true\n          # 是否将服务名称转换小写\n          lower-case-service-id: true\n      metrics:\n        enabled: true\n    sentinel:\n      enabled: false\n      namespace: sentinel\n      group-id: SENTINEL_GROUP\n      data-type: json\n      filter:\n        enabled: false\n      eager: true\n      transport:\n        dashboard: 127.0.0.1:8880\n        # 这个不能重复，不同模块不同的port\n        port: 8720\n        client-ip: 127.0.0.1\n      log:\n        dir: ./logs/sentinel\n      scg:\n        enabled: true\n        fallback:\n          mode: response\n          response-status: 426\n          response-body: \'{\"bizStatus\":426, \"bizCode\": \"frequent_requests\", \"bizMessage\":\"请求过于频繁，请稍后重试\"}\'\n      datasource:\n        # 流量控制\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.discovery.server-addr}\n            namespace: ${spring.cloud.sentinel.namespace}\n            data-id: ${spring.application.name}-gateway-flow-rules\n            group-id: ${spring.cloud.sentinel.group-id}\n            rule-type: gw-flow\n            data-type: ${spring.cloud.sentinel.data-type}\n            username: ${spring.cloud.nacos.discovery.username}\n            password: ${spring.cloud.nacos.discovery.password}\n        # API管理规则\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.discovery.server-addr}\n            namespace: ${spring.cloud.sentinel.namespace}\n            data-id: ${spring.application.name}-gateway-api-group\n            group-id: ${spring.cloud.sentinel.group-id}\n            rule-type: gw-api-group\n            data-type: ${spring.cloud.sentinel.data-type}\n            username: ${spring.cloud.nacos.discovery.username}\n            password: ${spring.cloud.nacos.discovery.password}\n        # 熔断降级\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.discovery.server-addr}\n            namespace: ${spring.cloud.sentinel.namespace}\n            data-id: ${spring.application.name}-degrade-rules\n            group-id: ${spring.cloud.sentinel.group-id}\n            rule-type: degrade\n            data-type: ${spring.cloud.sentinel.data-type}\n            username: ${spring.cloud.nacos.discovery.username}\n            password: ${spring.cloud.nacos.discovery.password}\n        # 系统规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.discovery.server-addr}\n            namespace: ${spring.cloud.sentinel.namespace}\n            data-id: ${spring.application.name}-system-rules\n            group-id: ${spring.cloud.sentinel.group-id}\n            rule-type: system\n            data-type: ${spring.cloud.sentinel.data-type}\n            username: ${spring.cloud.nacos.discovery.username}\n            password: ${spring.cloud.nacos.discovery.password}\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 1\n          thread-pool-name: kafkaListerThreadPool\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n          # 消息堆积量最大值（该参数和maxOverloadCount判断是否需要扩容）\n          maxLag: 50000\n          # 消息堆积量最小值（通过该参数判断是否需要缩容）\n          minLag: 1000\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-gatewayLog-topic\n            group: iwindplus-gatewayLog-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-appCert-topic\n            group: iwindplus-appCert-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-apiWhiteList-topic\n            group: iwindplus-apiWhiteList-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-ipBlackList-topic\n            group: iwindplus-ipBlackList-group\n            # 是否自动创建\n            auto-create: true\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret:}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret:}\n    stack:\n      max-length: -1\n      max-frames: -1\nknife4j:\n  gateway:\n    enabled: true\n    # 指定服务发现的模式聚合微服务文档\n    strategy: discover\n    discover:\n      enabled: true\n      # 指定版本号(Swagger2|OpenAPI3)\n      version : OpenAPI3\n      # 需要排除的微服务(eg:网关服务)\n      excluded-services:\n        - iwindplus-auth\n        - iwindplus-im-ws\n        - iwindplus-monitor\n    basic:\n      enable: false\n      username: ${knife4j-gateway-username:admin}\n      password: ${knife4j-gateway-password:zaq12wsx}', '51a61975ba5e5248b514242fcaf86add', '2026-08-30 22:35:00', '2026-08-30 22:35:00', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (17, 17247, 'iwindplus-auth-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9002\n  servlet:\n    application-display-name: 认证服务\n    session:\n      tracking-modes: cookie\ncross:\n  # 是否开启跨域\n  enabled: false\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nauth:\n  # 是否启用校验访问token过期\n  enabled-token-expired-valid: false\n  log:\n    # 是否开启登录日志审计\n    enabled: true\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerThreadPool\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      queueTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: disruptorThreadPool\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerThreadPool\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-loginLog-topic\n            group: iwindplus-loginLog-group\n            # 是否自动创建\n            auto-create: true\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret:}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret:}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.auth.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '3041352ec25a89588cd5fe11d5b8d108', '2026-08-30 22:35:05', '2026-08-30 22:35:05', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (21, 17249, 'iwindplus-log-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9003\n  servlet:\n    application-display-name: 日志服务\ncross:\n  # 是否开启跨域\n  enabled: false\n\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\n\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      platformIds: [ 1 ]\n      runTimeout: 5000\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerThreadPool\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      queueTimeout: 0\n      runTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: disruptorThreadPool\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  elasticsearch:\n    uris: http://127.0.0.1:9200\n    username: ${elasticsearch-username}\n    password: ${elasticsearch-password}\n    connection-timeout: 5s\n    socket-timeout: 30s\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerThreadPool\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          # 是否异步提交（并发情况）\n          enable-async-acks: true\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n          # 消息堆积量最大值（该参数和overloadLagThreshold判断是否需要扩容）\n          maxLag: 5\n          # 消息堆积量最小值（该参数和idleLagThreshold判断是否需要缩容）\n          minLag: 2\n          # 连续高lag阈值（该参数和maxLag判断是否需要扩容）\n          overloadLagThreshold: 5\n          # 连续低lag阈值（该参数和minLag判断是否需要缩容）\n          idleLagThreshold: 5\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-gatewayLog-topic\n            group: iwindplus-gatewayLog-group\n            # 是否自动创建\n            auto-create: true\n          - topic: iwindplus-loginLog-topic\n            group: iwindplus-loginLog-group\n            # 是否自动创建\n            auto-create: true\ndisruptor:\n  multi:\n    # 是否开启\n    enabled: true\n    configs:\n      # 对应kafka group\n      iwindplus-gatewayLog-group:\n        # 是否启用监控观察\n        enabled-observation: true\n        # 环形缓冲区大小\n        ring-buffer-size: 65536\n        # 生产者类型\n        producer-type: SINGLE\n        # 等待策略\n        wait-strategy: YIELDING\n        # 等待超时时间\n        timeout: 10\n        # 阻塞等待超时单位\n        time-unit: MILLISECONDS\n        # work线程池名称\n        thread-pool-name: disruptorThreadPool\n        # 恢复比例\n        resume-threshold: 0.5\n        # 暂停比例\n        pause-threshold: 0.1\n      iwindplus-loginLog-group:\n        # 是否启用监控观察\n        enabled-observation: true\n        # 环形缓冲区大小\n        ring-buffer-size: 65536\n        # 生产者类型\n        producer-type: SINGLE\n        # 等待策略\n        wait-strategy: YIELDING\n        # 等待超时时间\n        timeout: 10\n        # 阻塞等待超时单位\n        time-unit: MILLISECONDS\n        # work线程池名称\n        thread-pool-name: disruptorThreadPool\n        # 恢复比例\n        resume-threshold: 0.5\n        # 暂停比例\n        pause-threshold: 0.1\n# 地址服务配置\naddress:\n  # 是否启用地址服务\n  enabled: true\n  # 提供商配置列表\n  providers:\n    # 百度地图\n    baidu:\n      enabled: true\n      priority: 1\n      api-key: FFdlqXfexz0JOLmeTjhQqbOKPlteJLNJ\n      secret-key: ${address-baidu-secret-key}\n    # 高德地图\n    gaode:\n      enabled: true\n      priority: 2\n      api-key: 67e33f0347b5fa1d5d01977fd603414a\n      secret-key: ${address-gaode-secret-key}\n    # 腾讯地图\n    tencent:\n      enabled: true\n      priority: 3\n      api-key: GJMBZ-FCDWN-AFWFA-SP6NA-2RGVV-SCFN2\n      secret-key: ${address-tencent-secret-key}\n    # 138ip\n    ip138:\n      enabled: true\n      priority: 4\n      secret-key: ${address-138ip-secret-key}\n    # 太平洋网络（免费）\n    pconline:\n      enabled: true\n      priority: 5\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: ${xxl-job-access-token}\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.log.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', 'd85fd23264666639c598a1a6203bd33d', '2026-08-30 22:35:10', '2026-08-30 22:35:10', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (23, 17251, 'iwindplus-im-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9004\n  servlet:\n    application-display-name: 即时通讯服务\ncross:\n  # 是否开启跨域\n  enabled: false\nim:\n  # 是否启用远程token校验\n  enabled-remote-token: false\n  # 聊天群扫码加入地址\n  chatGroupScanUrl: https://www.iwindplus.com/im/joinChatGroup\n  mail:\n    # 邮件模板编码\n    tpl-code: c3f67fd355dd6098156053f68285ba3e\n  sms:\n    # 短信配置编码\n    code: 6856e64cc228215d44c1a351454a8cc5\n    # 短信模板编码\n    tpl-code: c3f67fd354dd6098154053f68285ba35\n  oss:\n    # 对象存储模板编码\n    tpl-code: c3f67fd355dd6098156053f68385ba35\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-im?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: ${mysql-username}\n    # 数据库密码\n    password: ${mysql-password}\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\n  elasticsearch:\n    uris: http://127.0.0.1:9200\n    username: ${elasticsearch-username}\n    password: ${elasticsearch-password}\n    connection-timeout: 5s\n    socket-timeout: 30s\nwebsocket:\n  server:\n    # 是否开启websocket\n    enabled: true\n    # 是否开启debug\n    debug: true\n    # 是否使用队列发送消息\n    useQueueSend: true\n    # 是否使用队列解码消息\n    useQueueDecode: true\n    # 解码出现异常时，是否打印异常日志\n    logWhenDecodeError: true\n    # websocket服务名称\n    name: ${spring.application.name}-ws\n    #  websocket服务端口\n    port: 9326\n    # 心跳超时时间\n    heartbeat-timeout: 0\n  ssl:\n    # 密钥库存储路径\n    keyStore:\n    # 信任存储路径\n    trustStore:\n    # 密钥库密码\n    password:\n  cluster:\n    # 是否开启集群\n    enabled: true\n    # 发消息到组\n    group: true\n    # 发消息给指定业务ID\n    bs-id: true\n    #  发消息给指定用户\n    user: true\n    # 发送到指定ip\n    ip: true\n    # 发消息给指定通道\n    channel: true\n    # 发消息到所有连接\n    all: true\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      public-key: ${mybatis-field-crypto-public-key:}\n      # 私钥\n      private-key: ${mybatis-field-crypto-private-key:}\n      # 密钥\n      key: ${mybatis-field-crypto-key:}\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.im.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', 'f41d6d27001b19f5928e3d96f6d3645a', '2026-08-30 22:35:15', '2026-08-30 22:35:15', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (27, 17253, 'iwindplus-flow-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9007\n  servlet:\n    application-display-name: 流程服务\ncross:\n  # 是否开启跨域\n  enabled: false\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-flow?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: ${mysql-password}\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: ${xxl-job-access-token}\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      public-key: ${mybatis-field-crypto-public-key:}\n      # 私钥\n      private-key: ${mybatis-field-crypto-private-key:}\n      # 密钥\n      key: ${mybatis-field-crypto-key:}\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.flow.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '847cd81ee9fd7ea3a85a9d8d5830c99e', '2026-08-30 22:35:20', '2026-08-30 22:35:20', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (29, 17255, 'iwindplus-monitor-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  #配置启动的接口\n  port: 9005\n  servlet:\n    application-display-name: 监控服务\nspring:\n  security:\n    user:\n      name: ${login-security-username}\n      password: ${login-security-password}\n  boot:\n    admin:\n      ui:\n        public-url: http://127.0.0.1:9005\n      notify:\n        mail:\n          from: zengdeguiu88@163.com\n          to: 845875725@qq.com\n      monitor:\n        default-timeout: 30000\n      discovery:\n        ignored-services:\n          - iwindplus-im-ws\n  mail:\n    port: 465\n    host: smtp.163.com\n    username: zengdeguiu88@163.com\n    password: ${mail-password}\n    default-encoding: UTF-8\n    properties:\n      mail:\n        smtp:\n          ssl:\n            enable: true\n          auth: true\n          starttls:\n            enable: true\n            required: true\n          socketFactory:\n            port: ${spring.mail.port}\n            class: javax.net.ssl.SSLSocketFactory', 'e1c3ae50f450a75a8e36d92efb2945c9', '2026-08-30 22:35:39', '2026-08-30 22:35:39', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (45, 17257, 'iwindplus-binlog-producer-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9008\n  servlet:\n    application-display-name: binlog生产者\ncross:\n  # 是否开启跨域\n  enabled: false\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: binlogThreadPool\n      threadPoolAliasName: binlog线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 0\n      platformIds: [ 1 ]\n      preStartAllCoreThreads: true\n    - threadPoolName: binlogSchedulerThreadPool\n      threadPoolAliasName: binlog调度线程池\n      executorType: scheduled\n      corePoolSize: 5\n      maximumPoolSize: 10\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerThreadPool\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 0\n      queueTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: disruptorThreadPool\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: false\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          enable-reactive: true\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerThreadPool\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-binlog-topic\n            group: iwindplus-binlog-group\n            # 是否自动创建\n            auto-create: true\nbinlog:\n  # 是否开启binlog\n  enabled: true\n  # topic前缀（发送数据）\n  topic-prefix: iwindplus-binlog-topic\n  data-sources:\n    - type: mysql\n      server-id: 1\n      host: 127.0.0.1\n      port: 3317\n      username: ${binlog-mysql-username}\n      password: ${binlog-mysql-password}\n      # 包含的数据库\n      database-include-list: iwindplus-mgt\n      # 排除的数据库\n      database-exclude-list:\n      # 包含的表\n      table-include-list: iwindplus-mgt.user\n      # 排除的的表\n      table-exclude-list:\n  # binlog 消费位点\n  offset:\n    topic: ${binlog.topic-prefix}-offset\n    replication-factor: -1\n    num-partitions: -1\n  # 同步表结构变化历史\n  history:\n    topic: ${binlog.topic-prefix}-schema-history\n    replication-factor: -1\n    num-partitions: -1\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.binlog.producer.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '31addb2b8d28beefd4504c6481739540', '2026-08-30 22:35:43', '2026-08-30 22:35:43', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (47, 17259, 'iwindplus-binlog-consumer-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9009\n  servlet:\n    application-display-name: binlog消费者\ncross:\n  # 是否开启跨域\n  enabled: false\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\nswagger:\n  server-api:\n    # 是否启用API注册\n    enabled: true\n    # 最大重试次数\n    maxRetry: 5\n    # 重试间隔时间（单位：秒）\n    retryInterval: 3\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: binlogThreadPool\n      threadPoolAliasName: binlog线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: kafkaListerThreadPool\n      threadPoolAliasName: kafka默认集群监听线程池\n      executorType: eager\n      corePoolSize: 8\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 0\n      queueTimeout: 0\n      platformIds: [ 1 ]\n    - threadPoolName: disruptorThreadPool\n      threadPoolAliasName: disruptor线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nkafka:\n  multi:\n    enabled: true\n    # 是否启用动态扩容\n    enabled-scale: true\n    default-cluster: default\n    enabled-dynamic-register: true\n    clusters:\n      default:\n        bootstrap-servers: 127.0.0.1:9092\n        # 生产者配置\n        producer:\n          client-id: default-producer\n          retries: 5\n          batch-size: 16384\n          linger-ms: 10\n          buffer-memory: 67108864\n          acks: all\n          enabled-dempotence: true\n          compression-type: lz4\n          enable-transaction: false\n          transaction-id-prefix: default-tx-\n          max-block-ms: 60000\n          request-timeout-ms: 30000\n          max-request-size: 1048576\n          max-in-flight-requests-per-connection: 5\n          reconnect-backoff-ms: 1000\n          retry-backoff-ms: 500\n          properties:\n            max.in.flight.requests.per.connection: 3\n        # 消费者配置\n        consumer:\n          group: default-consumer-group\n          client-id: default-consumer\n          concurrency: 3\n          thread-pool-name: kafkaListerThreadPool\n          enable-auto-commit: false\n          ack-mode: MANUAL\n          auto-commit-interval-ms: 1000\n          auto-offset-reset: earliest\n          max-poll-records: 500\n          max-poll-interval-ms: 600000\n          session-timeout-ms: 10000\n          heartbeat-interval-ms: 3000\n          fetch-min-bytes: 1\n          fetch-max-bytes: 524288\n          max-partition-fetch-bytes: 1048576\n          enabled-batch-listener: true\n          ack-count: 1\n          ack-time: 10000\n          properties:\n            fetch.max.wait.ms: 500\n          # 是否启用死信主题\n          enabled-dlt: true\n        # 绑定关系配置\n        bindings:\n          - topic: iwindplus-binlog-topic\n            group: iwindplus-binlog-group\n            # 是否自动创建\n            auto-create: true\ndisruptor:\n  multi:\n    # 是否开启\n    enabled: true\n    configs:\n      # 对应kafka group\n      iwindplus-binlog-group:\n        # 环形缓冲区大小\n        ring-buffer-size: 65536\n        # 生产者类型\n        producer-type: SINGLE\n        # 等待策略\n        wait-strategy: YIELDING\n        # 等待超时时间\n        timeout: 10\n        # 阻塞等待超时单位\n        time-unit: MILLISECONDS\n        # work线程池名称\n        thread-pool-name: disruptorThreadPool\nbinlog:\n  consumer:\n    # 是否开启\n    enabled: true\n    databases:\n      # 数据库名称\n      iwindplus-mgt:\n        # 密钥（验签用）\n        secret-key: ${binlog-db-iwindplus-mgt-secret-key}\n        # 需要验签的表\n        table-list:\n          - user\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/20f6845c-7040-4c81-a409-77eba662316c\n      secret: ${binlog-webhook-secret}\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a9b7d7e706f8dbd3\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.binlog.consumer.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '6474dce57221f3be1b0374eb43293776', '2026-08-30 22:35:47', '2026-08-30 22:35:47', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (83, 17261, 'iwindplus-dtx-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9012\n  servlet:\n    application-display-name: 分布式事务服务\ncross:\n  # 是否开启跨域\n  enabled: false\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: tccThreadPool\n      threadPoolAliasName: tcc分布式事务线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-dtx?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: ${mysql-password}\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\nxxl-job:\n  enabled: true\n  admin:\n    addresses: http://127.0.0.1:9880/xxl-job-admin\n    access-token: ${xxl-job-access-token}\n  executor:\n    log-path: logs/job\n    log-retention-days: 30\n    app-name: ${spring.application.name}\n    ip: host.docker.internal\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 是否启用签名（数据防篡改用）\n      enabled-sign: true\n      # 密钥（数据防篡改用）\n      secret-key: ${mybatis-field-crypto-secret-key}\n      # 算法\n      algorithm: AES\n      # 公钥\n      public-key: ${mybatis-field-crypto-public-key:}\n      # 私钥\n      private-key: ${mybatis-field-crypto-private-key:}\n      # 密钥\n      key: ${mybatis-field-crypto-key:}\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.dtx.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', '2e80f453af050ddad55778ec46eed2ee', '2026-08-30 22:35:56', '2026-08-30 22:35:56', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (91, 17263, 'iwindplus-common.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 优雅停机\n  shutdown: graceful\n  servlet:\n    encoding:\n      force: true\n      force-request: true\n      force-response: true\n  undertow:\n    threads:\n      io: 16\n      worker: 256\n    buffer-size: 1024\n    direct-buffers: true\nspring:\n  mvc:\n    path-match:\n      matching-strategy: ant_path_matcher\n  jmx:\n    enabled: true\n  lifecycle:\n    # 优雅停机时，每个生命周期阶段允许等待的最大时间\n    # 超过该时间后，Spring 将继续执行后续关闭流程\n    timeout-per-shutdown-phase: 60s\n  servlet:\n    multipart:\n      enabled: true\n      maxFileSize: 1GB\n      maxRequestSize: 10GB\n  messages:\n    basename: i18n/messages\n    fallback-to-system-locale: true\n    cache-duration: -1\n    # 是否开启远程消息源\n    enabled-remote: true\n    # nacos分组名称\n    group: I18N_GROUP\n  cloud:\n    circuitbreaker:\n      resilience4j:\n        enabled: true\n    loadbalancer:\n      cache:\n        # 开启缓存，如果注册中心有自己的缓存，那么就可以禁用loadbalancer的缓存\n        enabled: true\n        # 过期时间10s\n        ttl: 10\n        # 容量256M\n        capacity: 256\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    openfeign:\n      circuitbreaker:\n        # 开启服务熔断\n        enabled: true\n        group:\n          enabled: true\n      micrometer:\n        enabled: true\n      compression:\n        request:\n          enabled: false\n        response:\n          enabled: false\n      httpclient:\n        hc5:\n          enabled: true\n          connection-request-timeout: 3\n          socket-timeout: 10\n          pool-reuse-policy: fifo\n          pool-concurrency-policy: STRICT\n        # 默认连接超时时间：2000毫秒\n        connection-timeout: 5000\n        # 连接池管理定时器执行频率：默认 3000（单位：毫秒）\n        connection-timer-repeat: 5000\n        # 连接池最大连接数，默认200\n        max-connections: 500\n        # 每一个IP最大占用多少连接 默认 50\n        max-connections-per-route: 200\n        # 连接池中存活时间，默认为5\n        time-to-live: 10\n        time-to-live-unit: minutes\n        ok-http:\n          read-timeout: 10000\n      client:\n        config:\n          # default代表所有服务\n          default:\n            # 日志级别\n            loggerLevel: FULL\n            # feign客户端建立连接超时时间（单位：毫秒）\n            connect-timeout: 5000\n            # feign客户端建立连接后读取资源超时时间（单位：毫秒）\n            read-timeout: 10000\n      okhttp:\n        enabled: false\nfilter:\n  xss:\n    # 是否开启xss过滤器，防止攻击\n    enabled: true\n  request:\n    # 是否开启请求过滤器\n    enabled: true\n  # 过滤器加解密使用\n  crypto:\n    # 算法\n    algorithm: AES\n    # 公钥\n    public-key: ${filter-crypto-public-key:}\n    # 私钥\n    private-key: ${filter-crypto-private-key:}\n    # 密钥\n    key: ${filter-crypto-key:}\njackson:\n  # 是否开启自定义jackson配置\n  enabled: true\n  sensitive:\n    # 是否开启敏感数据脱敏，响应接口结果时用\n    enabled: false\nvalidator:\n  # 是否开启参数校验\n  enabled: true\n  # 是否快速失败返回模式\n  fail-fast: true\nkey:\n  generator:\n    # 是否开启唯一key\n    enabled: true\n    # key是否开启加密\n    enabled-crypto: true\nloadbalancer:\n  monitor:\n    enabled: true\n  gray:\n    enabled: true\n    # 灰度策略类型（whitelist: 白名单策略，percentage: 百分比策略）\n    strategy: PERCENTAGE\n    # 灰度百分比（0-100）\n    percentage: 10\nglobal:\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\nresponse:\n  body:\n    enabled: true\n    crypto:\n      # 是否开启加密功能，默认关闭\n      enabled: false\n      # 算法\n      algorithm: RSA\n      # 公钥\n      public-key: ${response-body-crypto-public-key:}\n      # 私钥\n      private-key: ${response-body-crypto-private-key:}\n      # 密钥\n      key: ${response-body-crypto-key:}\nhttp:\n  client:\n    api-protection:\n      # 是否开启API防护\n      enabled: true\n      enabled-remote: false\n      access-key: ${httpClient-apiProtection-access-key:}\n      secret-key: ${httpClient-apiProtection-secret-key:}\nfeign:\n  request:\n    # 是否开启请求拦截器，传递请求头信息\n    enabled: true\n  error:\n    # 是否开启全局异常捕获\n    enabled: true\n  fallback:\n    # 是否启用熔断回退\n    enabled: true\n  sentinel:\n    enabled: true\ndynamictp:\n  enabled: true\n  enabledCollect: true\n  enabledBanner: false\n  collectorTypes: micrometer\n  monitorInterval: 5\n  platforms:\n    - platform: lark\n      platformId: 1\n      webhook: https://open.feishu.cn/open-apis/bot/v2/hook/cbdc5945-1cf9-42e4-84d5-a46ce56c99ef\n  globalExecutorProps:\n    rejectedHandlerType: CallerRunsPolicy\n    queueType: VariableLinkedBlockingQueue\n    waitForTasksToCompleteOnShutdown: true\n    awaitTerminationSeconds: 3\n    taskWrapperNames: [ \"micrometer\", \"ttl\", \"mdc\" ]\n    queueTimeout: 300\n    runTimeout: 300\n    notifyEnabled: true\nlogging:\n  level:\n    root: INFO\n  console:\n    enabled: true\n    enabled-async: true\n  logstash:\n    enabled: true\n    enabled-async: true\n    address: 127.0.0.1:4560\n  config: classpath:logback-spring.xml\nmanagement:\n  observations:\n    enable:\n      http: true\n  server:\n    port: ${server.port}\n  endpoints:\n    jmx:\n      exposure:\n        include: \"*\"\n    web:\n      exposure:\n        include: health,info,circuitbreakers,metrics,ratelimiters,bulkheads,retries,prometheus,logfile\n        exclude: env,heapdump,threaddump,mappings\n  otlp:\n    tracing:\n      endpoint: http://127.0.0.1:4318/v1/traces\n    metrics:\n      export:\n        url: http://127.0.0.1:4318/v1/metrics\n  metrics:\n    tags:\n      application: ${spring.application.name}\n    distribution:\n      percentiles-histogram:\n        http.server.requests: true\n  tracing:\n    enabled: true\n    sampling:\n      probability: 1.0\n    propagation:\n      type:\n        - W3C\n', 'e1bc12ebffe56a6957d0183153b0aa7f', '2026-08-30 22:36:01', '2026-08-30 22:36:01', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (93, 17265, 'iwindplus-circuitbreaker.yml', 'IWINDPLUS_GROUP', '', '# 全局默认熔断策略\nresilience4j:\n  circuitbreaker:\n    enabled: true\n    configs:\n      default:\n        # 失败率阈值，达到50%触发熔断\n        failureRateThreshold: 50\n        # 慢调用率阈值\n        slowCallRateThreshold: 80\n        # 慢调用时间阈值（毫秒）\n        slowCallDurationThreshold: 1000\n        # 熔断器开启持续时间（秒）\n        waitDurationInOpenState: 10s\n        # 允许半开状态的最大调用数\n        permittedNumberOfCallsInHalfOpenState: 3\n        # 滑动窗口大小\n        slidingWindowSize: 10\n        # 最小调用次数才计算失败率\n        minimumNumberOfCalls: 5\n        # 自动从打开状态过渡到半开状态\n        automaticTransitionFromOpenToHalfOpenEnabled: true\n        # 仅 Feign 技术类异常计入失败；业务、认证、限流异常不触发熔断\n        record-exceptions:\n          - com.iwindplus.base.feign.exception.FeignTechnicalException\n          - feign.RetryableException\n          - java.io.IOException\n          - java.util.concurrent.TimeoutException\n        ignore-exceptions:\n          - com.iwindplus.base.feign.exception.FeignBusinessException\n          - com.iwindplus.base.feign.exception.FeignAuthenticationException\n          - com.iwindplus.base.feign.exception.FeignRateLimitException\n    # 留空即可，全部走 default\n    instances: {}\n  timelimiter:\n    configs:\n      default:\n        # 单次调用硬超时 3 s（覆盖 Feign 默认 1 s）\n        timeout-duration: 3s\n  # 重试配置（可选）\n  retry:\n    configs:\n      default:\n        # 含首次，共 3 次\n        max-attempts: 3\n        wait-duration: 500ms\n        enable-exponential-backoff: true\n        exponential-backoff-multiplier: 1.5\n  # 限流配置（可选）\n  ratelimiter:\n    configs:\n      default:\n        limit-for-period: 10\n        limit-refresh-period: 1s\n        timeout-duration: 1000\n  # 隔离配置（可选）\n  bulkhead:\n    configs:\n      default:\n        maxConcurrentCalls: 10\n        maxWaitDuration: 0', '0b3d224dd2f8a7c443f1b082ec602456', '2026-08-30 22:36:06', '2026-08-30 22:36:06', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` (`id`, `nid`, `data_id`, `group_id`, `app_name`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `op_type`, `tenant_id`, `encrypted_data_key`, `publish_type`, `gray_name`, `ext_info`) VALUES (25, 17267, 'iwindplus-setup-local.yml', 'IWINDPLUS_GROUP', '', 'server:\n  # 配置启动的接口\n  port: 9006\n  servlet:\n    application-display-name: 通用设置服务\ncross:\n  # 是否开启跨域\n  enabled: false\noperate:\n  enabled: true\n  log:\n    # 是否开启操作日志审计\n    enabled: true\n    # 是否启用获取请求参数\n    enabled-request-param: true\n    # 是否启用获取请求体\n    enabled-request-body: true\n    # 是否启用获取响应体\n    enabled-response-body: true\n  valid:\n    # 是否开启操作配置校验\n    enabled: true\n    # 是否开启GA校验\n    enabled-ga: true\n    # 是否开启邮箱校验\n    enabled-mail: false\n    # 是否开启短信校验\n    enabled-sms: false\ndynamictp:\n  executors:\n    - threadPoolName: asyncThreadPool\n      threadPoolAliasName: 异步线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: i18nThreadPool\n      threadPoolAliasName: 国际化线程池\n      executorType: eager\n      corePoolSize: 2\n      maximumPoolSize: 4\n      queueCapacity: 50\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: idempotentSchedulerThreadPool\n      threadPoolAliasName: 幂等调度线程池\n      executorType: scheduled\n      corePoolSize: 2\n      maximumPoolSize: 4\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: httpClientThreadPool\n      threadPoolAliasName: http调用客户端线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: ossThreadPool\n      threadPoolAliasName: 对象存储线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\n    - threadPoolName: smsThreadPool\n      threadPoolAliasName: 短信线程池\n      executorType: eager\n      corePoolSize: 16\n      maximumPoolSize: 32\n      queueCapacity: 100\n      runTimeout: 5000\n      platformIds: [ 1 ]\nspring:\n  # 初始化数据库\n  flyway:\n    enabled: true\n    placeholder-replacement: false\n    baseline-on-migrate: true\n    locations: classpath:db\n    table: flyway_schema_history\n    url: ${spring.datasource.url}\n    user: ${spring.datasource.username}\n    password: ${spring.datasource.password}\n  datasource:\n    # 数据库url\n    url: jdbc:mysql://127.0.0.1:3317/iwindplus-setup?useUnicode=true&autoReconnect=true&characterEncoding=utf8&rewriteBatchedStatements=true&useConfigs=maxPerformance&useSSL=false&allowMultiQueries=true&serverTimezone=GMT%2B8\n    # 数据库用户名\n    username: root\n    # 数据库密码\n    password: ${mysql-password}\n    # Hikari 连接池配置\n    hikari:\n      # 数据库连接超时时间\n      connectionTimeout: 30000\n      # 最小空闲连接数量\n      minimumIdle: 5\n      # 连接池最大连接数，默认是10\n      maximumPoolSize: 20\n      # 此属性控制池中连接的最长生命周期，值0表示无限生命周期，默认1800000即30分钟\n      maxLifetime: 1800000\n      connectionTestQuery: SELECT 1\n  cache:\n    redis:\n      time-to-live: 0\n  redis:\n    # 序列化类型\n    serialize-type: PROTOBUF\n    idempotent:\n      # 是否开启redis幂等（防重复提交）\n      enabled: true\n    lock:\n      # 是否开启redis锁\n      enabled: true\n    rate-limiter:\n      # 是否开启redis限流\n      enabled: true\n    redisson:\n      config: |\n        singleServerConfig:\n          address: redis://127.0.0.1:6379\n          password: ${redis-password}\n          database: 6\n          connectionMinimumIdleSize: 1\n          connectionPoolSize: 2\n          subscriptionConnectionMinimumIdleSize: 1\n          subscriptionConnectionPoolSize: 2\nseata:\n  enabled: true\n  enable-auto-data-source-proxy: true\n  data-source-proxy-mode: XA\n  application-id: ${spring.application.name}\n  # 事务分组名称，要和服务端对应\n  tx-service-group: iwindplus_tx_group\n  service:\n    vgroup-mapping:\n      # key是事务分组名称 value要和服务端的机房名称保持一致\n      iwindplus_tx_group: default\n    grouplist:\n      default: 127.0.0.1:8091\n    disable-global-transaction: false\nsms:\n  aliyun:\n    # 是否开启阿里云短信\n    enabled: true\n  qiniu:\n    # 是否开启七牛云短信\n    enabled: true\n  lingkai:\n    # 是否开启凌凯短信\n    enabled: true\n  mxtong:\n    # 是否开启麦讯通短信\n    enabled: true\noss:\n  minio:\n    # 是否开启minio\n    enabled: true\n  aliyun:\n    # 是否开启阿里云OSS\n    enabled: true\n  qiniu:\n    # 是否开启七牛云OSS\n    enabled: true\nvod:\n  aliyun:\n    # 是否开启阿里云VOD\n    enabled: true\nwechat:\n  ma:\n    # 是否开启微信小程序\n    enabled: true\n  mp:\n    # 是否开启微信公众号\n    enabled: true\nocr:\n  print-word:\n    # 是否开启打印文字\n    enabled: true\n    # 应用编码\n    app-code: ${ocr-print-word-app-code}\n  xiangyun:\n    # 是否开启翔云\n    enabled: true\n    # 访问key\n    accessKey:\n    # 密钥\n    secretKey:\nmybatis-plus:\n  type-aliases-package: com.iwindplus.**.model,com.iwindplus.**.domain\n  executor-type: REUSE\n  configuration:\n    use-column-label: true\n    call-setters-on-nulls: true\n    map-underscore-to-camel-case: true\n    cache-enabled: true\n    # 打印sql\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    db-config:\n      id-type: ASSIGN_ID\n  field:\n    fill:\n      #  是否开启字段填充\n      enabled: true\n      # 是否开启插入严格模式\n      enabled-insert-strict: true\n    crypto:\n      # 是否开启\n      enabled: true\n      # 是否启用输入加密\n      enabled-input-encrypt: true\n      # 是否启用输入脱敏\n      enabled-input-sensitive: false\n      # 是否启用输出解密\n      enabled-output-decrypt: true\n      # 算法\n      algorithm: AES\n      # 公钥\n      public-key: ${mybatis-field-crypto-public-key:}\n      # 私钥\n      private-key: ${mybatis-field-crypto-private-key:}\n      # 密钥\n      key: ${mybatis-field-crypto-key:}\nalert:\n  # 飞书\n  feishu:\n    app-id: cli_a92f34e733b81cd1\n    app-secret: ${alert-feishu-app-secret:}\n  log:\n    enabled: true\n    webhook:\n      url: https://open.feishu.cn/open-apis/bot/v2/hook/e479bf95-3d8e-43a3-9d38-7f0db242c9d8\n      secret: ${alert-feishu-webhook-secret:}\n    stack:\n      max-length: -1\n      max-frames: -1\nspringdoc:\n  packagesToScan:\n    - com.iwindplus.setup.server.web\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn', 'fdf2cbe73534adc91973e903fc5f430c', '2026-08-30 23:30:27', '2026-08-30 23:30:27', 'nacos', '192.168.65.1', 'U', 'iwindplus-local', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
COMMIT;

